if (call.name === 'send_email') {
  // Never auto-run. Show Maya the draft first.
  return { status: 'needs_confirmation', draft: call.input };
}
if (call.name === 'search_notes') {
  // Uses Maya's token, so RLS limits it to her notes
  return searchNotes(userClient, call.input.query);
}

const { data: { user } } = await supabase.auth.getUser();
if (!user) return new Response('Log in first', { status: 401 });
if (!(await limiter.allow(user.id))) {
  return new Response('Slow down', { status: 429 });
}
